<section class="section-heading reveal"><div><h2>Кассы</h2><p>Точки приёма платежей. Создавать и изменять их могут только директор и заместитель директора.</p></div></section>
<section class="finance-admin-grid">
    <article class="panel reveal"><div class="panel__header"><div><p class="page-eyebrow">Новая точка продаж</p><h3>Добавить кассу</h3></div></div><form method="post" action="<?= e(url('/education/kassas')) ?>" class="stacked-form"><?= csrf_field() ?><label class="field"><span class="field__label">Название</span><span class="field__control"><input name="name" required maxlength="120" placeholder="Касса на Ленина"></span></label><label class="field"><span class="field__label">Описание</span><span class="field__control"><textarea name="description" rows="3" placeholder="Адрес или назначение кассы"></textarea></span></label><input type="hidden" name="status" value="active"><button class="button button--primary" type="submit">Создать кассу</button></form></article>
    <div class="kassa-grid"><?php foreach ($kassas as $kassa): ?><article class="panel reveal kassa-card"><div class="kassa-card__top"><span class="metric-icon metric-icon--green"><?= icon('grid', 22) ?></span><span class="status-pill status-pill--<?= $kassa['status'] === 'active' ? 'active' : 'blocked' ?>"><i></i><?= $kassa['status'] === 'active' ? 'Действует' : 'Отключена' ?></span></div><h3><?= e($kassa['name']) ?></h3><p><?= e($kassa['description'] ?: 'Описание не указано') ?></p><strong><?= e(number_format((float) $kassa['received_total'], 2, ',', ' ')) ?> ₽</strong><small>Принято платежей: <?= (int) $kassa['payment_count'] ?></small><details class="embedded-form"><summary>Изменить</summary><form method="post" action="<?= e(url('/education/kassas/' . $kassa['id'] . '/update')) ?>" class="stacked-form"><?= csrf_field() ?><input name="name" value="<?= e($kassa['name']) ?>" required><textarea name="description" rows="2"><?= e($kassa['description']) ?></textarea><select name="status"><option value="active" <?= $kassa['status'] === 'active' ? 'selected' : '' ?>>Действует</option><option value="inactive" <?= $kassa['status'] === 'inactive' ? 'selected' : '' ?>>Отключена</option></select><button class="button button--secondary" type="submit">Сохранить</button></form></details></article><?php endforeach; ?><?php if (!$kassas): ?><div class="panel empty-state"><span><?= icon('grid', 28) ?></span><h3>Касс пока нет</h3><p>Добавьте точку приёма оплаты.</p></div><?php endif; ?></div>
</section>
